/**
 * Small software drawing kit for the bottom screen.
 *
 * Everything the UI needs is drawn into a 320x240 RGB565 canvas in ordinary
 * memory, which is then copied to the bottom framebuffer once per update. The
 * 3DS GPU is not involved: the UI is redrawn only when something changes, so a
 * plain rectangle/circle/text rasteriser costs far less than setting up the
 * 1-bit or RGBA texture pipeline would, and it keeps the whole interface in one
 * file with no GPU state to get wrong.
 *
 * Text is anti-aliased from pre-baked 4-bit coverage atlases (ui_font.c,
 * generated by tools/make-font.py).
 *
 * MIT licensed. The layout language (round panels, tabs, toggle pills, touch
 * hit-testing) follows bheppe's gpsp-3d, which is GPLv2 - only the look was
 * taken from it, not its code.
 */
#pragma once

#include <stdbool.h>
#include <stdint.h>

#define UI_W 320
#define UI_H 240

/* One glyph: top-left relative to the drawing origin, size, advance, and offset
 * into the font's coverage data. */
typedef struct
{
	int8_t x, y;
	uint8_t w, h;
	uint8_t adv;
	uint32_t off;
} ui_glyph;

typedef struct
{
	int height;   /* line height */
	int ascent;   /* pixels above the baseline */
	const ui_glyph *g;
	const unsigned char *bits;
} ui_font;

extern const ui_font ui_font_small, ui_font_body, ui_font_bold, ui_font_title,
	ui_font_big;

#define UI_RGB(r, g, b) \
	((uint16_t)((((r) >> 3) << 11) | (((g) >> 2) << 5) | ((b) >> 3)))

extern uint16_t ui_canvas[UI_W * UI_H];

void ui_clear(uint16_t c);
void ui_fill(int x, int y, int w, int h, uint16_t c);
void ui_fill_alpha(int x, int y, int w, int h, uint16_t c, int alpha);
void ui_vgradient(int x, int y, int w, int h, uint16_t top, uint16_t bottom);
void ui_rrect(int x, int y, int w, int h, int r, uint16_t c);
void ui_rrect_outline(int x, int y, int w, int h, int r, int t, uint16_t c);
void ui_circle(int cx, int cy, int r, uint16_t c);
/* dir: -1 left, 1 right, 2 up, -2 down */
void ui_arrow(int cx, int cy, int size, int dir, uint16_t c);

int ui_text_w(const ui_font *f, const char *s);
/* Draws s with its top-left at (x, y), clipped to max_w pixels with "..."
 * when max_w > 0. Returns the x after the text. */
int ui_text(const ui_font *f, int x, int y, const char *s, uint16_t c,
	    int max_w);
void ui_text_center(const ui_font *f, int cx, int y, const char *s, uint16_t c);
void ui_text_right(const ui_font *f, int rx, int y, const char *s, uint16_t c);
/* Vertically centred in a box of height h starting at y. */
int ui_text_vc(const ui_font *f, int x, int y, int h, const char *s, uint16_t c,
	       int max_w);

/* Copy the canvas to the bottom framebuffer and show it, all at once. For
 * menus and anything that is not inside the frame loop. */
void ui_present(void);

/* The same copy in bands, for the frame loop: the whole present is ~16 ms on
 * the console (transpose + 153 KiB cache flush), which is a dropped frame when
 * it happens in one go. Begin, then spend one band per frame where the waiting
 * is free, then swap.
 *
 *   ui_present_begin();                       canvas -> back buffer, band 0
 *   ... ui_present_band(cols) each frame ...  returns true on the last band
 *   ui_present_swap();                        show it
 *
 * Nothing is visible until the swap, so an interrupted or abandoned sequence
 * cannot show a half-updated screen; ui_present() replaces one safely. */
bool ui_present_begin(void);
bool ui_present_band(int cols);
void ui_present_swap(void);
